'use strict';

const state = {portal:'tenant',tenantSession:null,conversations:[],conversation:null,tenantText:'',tenantSending:false,tenantError:'',tenantPendingText:'',tenantRetry:null,policyAssistant:null,policyText:'',policySourceReview:null,policyAdvanced:false,policyNudge:null,view:'cases', cases:[], caseDetails:{}, polling:false, detail:null, selected:null, policies:null, session:null, query:'', filter:'attention', recordTab:'evidence', inbox:[], draft:null, preview:null, policyDirty:false,policyWorking:null,buildCases:[]};
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr = value => Array.isArray(value) ? value : [];
const human = value => String(value ?? '').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const categories = {appliance:'Appliance',plumbing:'Plumbing',garden:'Garden',doors_locks:'Doors and locks',windows:'Windows',inspection:'Inspection',checkout_cleaning:'Checkout cleaning',checkout_refurbishment:'Checkout refurbishment',other:'Other / unclassified'};
const roles = {case_manager:'Case manager',policy_editor:'Policy editor',access_officer:'Access officer',approver:'Approver',reviewer:'Reviewer'};
const actionLabels = {clarify:'Ask for clarification',request_quote:'Request a quote',confirm_appointment:'Confirm an appointment',instruct_work:'Instruct work',supply_keys:'Supply keys',close_item:'Close a work item',archive:'Archive administratively'};
const categoryLabels = {other:'Other / detect from report',appliance:'Appliance',plumbing:'Plumbing',garden:'Garden',doors_locks:'Doors and locks',windows:'Windows',inspection:'Inspection',checkout_cleaning:'Checkout cleaning',checkout_refurbishment:'Checkout refurbishment'};
const factLabels = {identity:'Person and property',route:'Verified contact route',access:'Access permission',keys:'Key custody',authority:'Work authority',schedule:'Appointment details',evidence:'Supporting evidence',classification:'Work classification',completion:'Completion evidence',commitments:'Open commitments',total:'Total commitment',urgent:'Potential urgent hazard',supported:'Supported process'};
const factValues = {
 identity:['Mapping explicitly confirmed','Mapping explicitly not confirmed'],route:['Contact route verified','Contact route not verified'],access:['Permission explicitly granted for this scope','Permission explicitly refused or withdrawn'],keys:['Key custody confirmed for this method','Key custody not established'],authority:['Authority explicitly covers this work and provider','Authority explicitly does not cover this work'],schedule:['Appointment details agreed','Appointment details not agreed'],evidence:['Required supporting material is usable','Required supporting material is unavailable or unusable'],classification:['Classification matches the source report','Classification does not match the source report'],completion:['This work item is evidenced as complete','This work item is not complete'],commitments:['All commitments for this item are resolved','A commitment remains outstanding'],urgent:['Potential urgent hazard reported','No urgent hazard reported in this source'],supported:['Proposed action has a supported process','Proposed action is outside the supported process']
};
const iconNames={plus:'Plus',search:'Search',file:'FileText',shield:'ShieldCheck',clock:'Clock',check:'Check',hold:'Pause',people:'Users',refresh:'RotateCw',arrow:'ArrowRight',alert:'TriangleAlert',home:'House',message:'MessageCircle',settings:'Settings2',wrench:'Wrench',send:'ArrowUp',chevron:'ChevronRight',close:'X',spark:'ListChecks',history:'History',back:'ArrowLeft',done:'CircleCheck',thermometer:'Thermometer',window:'PanelsTopLeft'};
const icon = name => {const node=window.lucide?.icons?.[iconNames[name]||'FileText'];if(!node)return '';const svg=window.lucide.createElement(node);svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');return svg.outerHTML;};
const statusNames={ACT:'Ready to proceed',CLARIFY:'More information needed',WAIT:'Waiting for a reply',HUMAN_REVIEW:'Your decision needed',STOP_ACTION:'Action paused',NO_FURTHER_ACTION:'No action needed',UNASSESSED:'Ready to review',UNKNOWN:'Not established',PASS:'Check passed',FAIL:'Check not met',CONFLICT:'Conflicting evidence',verified_resolution:'Repair confirmed',administratively_archived:'Archived',succeeded:'Action recorded',uncertain:'Result needs checking'};
const statusBadge = (value,label) => `<span class="status ${esc(String(value || 'unknown').toLowerCase().replace(/[_ ]/g,'-'))}">${esc(label||statusNames[value]||statusNames[String(value||'UNKNOWN').toUpperCase().replace(/ /g,'_')]||human(value||'unknown'))}</span>`;
const fmtDate = value => {if(!value)return 'Not recorded'; const d=new Date(value); return isNaN(d)?esc(value):new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/London'}).format(d);};
const shortID = id => String(id || '').slice(0,12);
const caseOf = detail => detail?.case || detail || {};
const scopeEqual = (a,b) => !!a&&!!b&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>JSON.stringify(a[k])===JSON.stringify(b[k]));
const scopeMatches = (a,b) => !!a&&Object.keys(a).length>0&&Object.entries(a).every(([k,v])=>JSON.stringify(v)===JSON.stringify(b[k]));
const currentRole = () => state.session?.actor?.role;
const localDateInput = date => new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);
const getOutcome = c => c.decision?.outcome || c.outcome || c.stage || c.status || 'unassessed';
const currentScope = () => ({...state.detail?.case?.proposal?.scope,category:state.detail?.case?.category || '',property_ref:state.detail?.case?.property_ref || '',work_item:state.detail?.case?.proposal?.work_item || '',provider:state.detail?.case?.proposal?.provider || '',access_method:state.detail?.case?.proposal?.access_method || '',action:state.detail?.case?.proposal?.action || ''});
const scopeText = scope => typeof scope==='string'?scope:Object.entries(scope || {}).filter(([,v])=>v!==''&&v!=null).map(([k,v])=>`${human(k)}: ${typeof v==='object'?JSON.stringify(v):v}`).join(' · ');
const options = (map,selected) => Object.entries(map).map(([value,label])=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`).join('');

let activeRequests=0;
const requestControllers=new Map();
async function api(path, method='GET', body) {
 if(state.portal==='tenant'&&!path.startsWith('/api/tenant/'))throw new Error('Open the property management view to use staff tools.');
 const controller=new AbortController();requestControllers.set(controller,path);
 activeRequests++;
 try {
 const response = await fetch(path,{method,signal:controller.signal,headers:{'Content-Type':'application/json'},credentials:'same-origin',...(body!==undefined?{body:JSON.stringify(body)}:{})});
 let data; try {data=await response.json();} catch {data=null;}
 if(!response.ok) {const message=data?.detail || data?.error || data?.message || `The request could not be completed (${response.status}).`;throw new Error(typeof message==='string'?message:JSON.stringify(message));}
 return data;
 } finally {activeRequests--;requestControllers.delete(controller);}
}
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;$('#toast-region').appendChild(el);setTimeout(()=>el.remove(),6500);}
function empty(title,text,actions=''){return `<div class="empty-state"><div class="empty-mark">${icon('file')}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function modal(title,subtitle,body,wide=false){const d=$('#modal');d.classList.toggle('wide',wide);$('#modal-content').innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();}
function formFooter(label,extra=''){return `<div class="form-footer"><button type="button" class="btn" data-action="close-modal">Cancel</button>${extra}<button class="btn primary" type="submit">${esc(label)}</button></div>`;}
function field(label,name,value='',type='text',full=false,help=''){return `<div class="form-field ${full?'full':''}"><label for="${esc(name)}">${esc(label)}</label><input id="${esc(name)}" name="${esc(name)}" type="${esc(type)}" value="${esc(value)}">${help?`<small>${esc(help)}</small>`:''}</div>`;}
function selectField(label,name,map,value,full=false){return `<div class="form-field ${full?'full':''}"><label for="${esc(name)}">${esc(label)}</label><select id="${esc(name)}" name="${esc(name)}">${options(map,value)}</select></div>`;}
function textField(label,name,value='',help='',required=false){return `<div class="form-field full"><label for="${esc(name)}">${esc(label)}</label><textarea id="${esc(name)}" name="${esc(name)}" ${required?'required':''}>${esc(value)}</textarea>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function openReviewCount(){return state.cases.reduce((n,c)=>n+Number(c.open_reviews??c.review_count??c.open_review_count??0),0);}
function updateCounts(){ $('#case-count').textContent=state.cases.length; $('#review-count').textContent=openReviewCount(); }
async function refreshCases(){
 if(state.portal!=='manager')return;
 const data=await api('/api/cases');
 const cases=arr(data?.cases||data);
 const details=await Promise.all(cases.map(c=>api(`/api/cases/${encodeURIComponent(c.id)}`)));
 state.caseDetails=Object.fromEntries(details.map(d=>[d.case.id,d]));
 state.cases=cases.map(c=>({...c,open_reviews:arr(state.caseDetails[c.id]?.reviews).filter(r=>['open','pending','deferred'].includes(r.status)).length}));
 updateCounts();
}
async function loadDetail(id){state.selected=id;const detail=await api(`/api/cases/${encodeURIComponent(id)}`);if(state.selected!==id)return;state.detail=detail;}
async function refreshSelected(){await refreshCases();if(state.selected)await loadDetail(state.selected);render();}
async function navigate(view){if(state.portal!=='manager')return;state.view=view;$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='policies'){const fresh=await api('/api/policies');if(state.policies&&fresh.active.version!==state.policies.active.version){state.draft=null;state.policyWorking=null;state.preview=null;state.policyDirty=false;toast('The published policy changed. The editor now uses the current version.');}state.policies=fresh;state.preview=null;}if(view==='reviews')await loadInbox();render();}
async function loadInbox(){await refreshCases();const details=Object.values(state.caseDetails);state.inbox=details.flatMap(d=>arr(d.reviews).filter(r=>['open','pending','deferred'].includes(r.status)).map(r=>({...r,_case:d.case,_detail:d})));updateCounts();}
function render(){if(state.portal==='tenant'){renderTenant();return;}updateCounts();$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));if(state.view==='policies')renderPolicies();else if(state.view==='reviews')renderInbox();else renderCases();renderPolicyNudge();}

function managerGroup(c){const d=state.caseDetails[c.id]||{},decision=d.decision||c.decision||{},outcome=String(decision.outcome||getOutcome(c)).toUpperCase().replace(/ /g,'_');if(c.status==='verified_resolution'||c.status==='resolved'||c.completion_state==='verified for this work item')return 'resolved';if(c.status==='administratively_archived')return 'progress';if(arr(d.reviews).some(r=>['open','pending','deferred'].includes(r.status))||arr(d.actions).some(a=>a.status==='uncertain')||c.policy_pending||['HUMAN_REVIEW','STOP_ACTION','CLARIFY','UNASSESSED','OPEN'].includes(outcome))return 'attention';return 'progress';}
function casePriority(c){const d=state.caseDetails[c.id]||{},outcome=String(d.decision?.outcome||getOutcome(c)).toUpperCase().replace(/ /g,'_');if(arr(d.decision?.blockers).some(b=>b.key==='urgent'))return 100;if(arr(d.actions).some(a=>a.status==='uncertain'))return 95;if(outcome==='STOP_ACTION')return 90;if(arr(d.reviews).some(r=>['open','pending','deferred'].includes(r.status)))return 80;if(c.policy_pending)return 75;if(outcome==='CLARIFY')return 70;if(managerGroup(c)==='attention')return 60;if(outcome==='ACT')return 40;return 10;}
function caseQueueReason(c){const d=state.caseDetails[c.id]||{},reviews=arr(d.reviews).filter(r=>['open','pending','deferred'].includes(r.status));if(c.status==='administratively_archived')return 'Archived · repair completion not confirmed';if(managerGroup(c)==='resolved')return 'Completion recorded for this work item';if(arr(d.decision?.blockers).some(b=>b.key==='urgent'))return 'Potential urgent hazard · review first';if(arr(d.actions).some(a=>a.status==='uncertain'))return 'Check the last action before trying again';if(c.policy_pending)return 'Policy updated · check this request again';if(reviews.length)return `${reviews.length} ${reviews.length===1?'decision needs':'decisions need'} a person`;if(arr(d.actions).some(a=>a.status==='succeeded'))return 'Action recorded · repair not yet confirmed';return d.decision?.next_step||c.next_step||'Ready for its next step';}
function renderCases(){
 syncQueueSelection();
 const counts=Object.fromEntries(['attention','progress','resolved'].map(k=>[k,state.cases.filter(c=>managerGroup(c)===k).length]));
 $('#app').innerHTML=`<div class="page"><div class="page-heading manager-heading"><div><div class="eyebrow">Property management</div><h1>A clear view of what needs you.</h1><p>Prioritise decisions, keep requests moving, and see what is resolved.</p></div><div class="actions"><button class="btn" data-action="refresh-cases" aria-label="Refresh requests">${icon('refresh')}</button><details class="advanced-tools"><summary class="btn">${icon('settings')}Demo tools</summary><div class="advanced-tools-menu"><button class="btn" data-action="build-import">${icon('file')}Load a development case</button><p>Inspect an allowed BUILD case at a chosen point in its history.</p></div></details><button class="btn primary" data-action="new-case">${icon('plus')}New request</button></div></div><div class="metrics manager-metrics">${metric('Needs attention',counts.attention,'Decisions and missing information','people','attention')}${metric('In progress',counts.progress,'Requests moving to the next step','clock')}${metric('Resolved',counts.resolved,'Completion confirmed for the work','done')}</div><div class="workspace"><aside class="queue" aria-label="Maintenance requests"><div class="queue-heading"><h2>Your requests <span class="muted small">${state.cases.length}</span></h2><label class="search">${icon('search')}<input id="case-search" aria-label="Search requests" placeholder="Search property or request" value="${esc(state.query)}"></label><div class="queue-filter" aria-label="Filter requests"><button class="filter-chip ${state.filter==='attention'?'active':''}" data-filter="attention" aria-pressed="${state.filter==='attention'}">Needs attention</button><button class="filter-chip ${state.filter==='progress'?'active':''}" data-filter="progress" aria-pressed="${state.filter==='progress'}">In progress</button><button class="filter-chip ${state.filter==='resolved'?'active':''}" data-filter="resolved" aria-pressed="${state.filter==='resolved'}">Resolved</button></div></div><div id="case-list" class="case-list">${renderQueue()}</div><div class="queue-meta">${icon('shield')} Ordered by urgency and decisions needed</div></aside><section class="case-detail" aria-label="Request detail">${renderRequestDetail()}</section></div></div>`;
 renderPolicyNudge();
}
function metric(label,value,note,symbol,extra=''){return `<div class="metric ${extra}"><div><div class="metric-label">${esc(label)}</div><div class="metric-number">${esc(value)}</div><div class="metric-note">${esc(note)}</div></div><div class="metric-symbol">${icon(symbol)}</div></div>`;}
function syncQueueSelection(){if(!state.selected||!filteredCases().some(c=>c.id===state.selected)){const changed=state.selected!==null||state.detail!==null;state.selected=null;state.detail=null;return changed;}if(state.detail&&state.detail.case.id!==state.selected){state.detail=null;return true;}return false;}
function renderRequestDetail(){return state.detail?renderDetail():empty(state.cases.length?'Choose a request to see its next step':'Your requests will appear here',state.cases.length?'Open a request from the visible list to see what is known, what is missing and how to move it forward.':'Start a fictional request in the tenant view, or add one here to explore the workflow.',filteredCases().length||!state.cases.length?`<button class="btn" data-action="${state.cases.length?'open-first-request':'new-case'}">${state.cases.length?'Open the next request':'Add a request'} ${icon('arrow')}</button>`:'');}
function filteredCases(){const query=state.query.toLowerCase();return state.cases.filter(c=>(`${c.title} ${c.property_ref} ${c.id}`.toLowerCase().includes(query))&&managerGroup(c)===state.filter).sort((a,b)=>casePriority(b)-casePriority(a)||new Date(a.created_at||0)-new Date(b.created_at||0));}
function renderQueue(){const cases=filteredCases();return cases.length?cases.map(c=>{const d=state.caseDetails[c.id],group=managerGroup(c),queueOutcome=group==='resolved'?'verified_resolution':c.status==='administratively_archived'?c.status:d?.decision?.outcome||getOutcome(c);return `<button class="case-row ${c.id===state.selected?'selected':''}" data-case-id="${esc(c.id)}" aria-pressed="${c.id===state.selected}"><span class="case-row-ref"><span>${esc(c.property_ref||'Property not recorded')}</span><span>${fmtDate(c.last_assessed_at||c.updated_at||c.created_at)}</span></span><span class="case-row-title">${esc(c.title||'Maintenance request')}</span><span class="case-row-meta"><span>${esc(human(c.category||'Maintenance'))}</span>${statusBadge(queueOutcome,String(queueOutcome).toUpperCase().replace(/ /g,'_')==='NO_FURTHER_ACTION'?'Action recorded':undefined)}</span><span class="case-row-reason ${group!=='attention'?'case-row-progress':''}">${esc(caseQueueReason(c))}</span></button>`;}).join(''):empty(state.query?'No matching requests':state.filter==='attention'?'Nothing needs your attention':state.filter==='resolved'?'No confirmed repairs yet':'No requests in progress',state.query?'Try a different property or phrase.':state.filter==='attention'?'Requests with a decision or missing information will appear here.':state.filter==='resolved'?'A completed message or booking does not mean the repair is resolved.':'Requests that are moving ahead or waiting for a reply appear here.');}
function renderDetail(){const d=state.detail,c=d.case,p=c.proposal||{},decision=d.decision,checks=arr(decision?.checks),blockers=arr(decision?.blockers),outcome=String(decision?.outcome||'UNASSESSED').toUpperCase().replace(/ /g,'_'); const alreadyExecuted=arr(d.actions).some(a=>a.status==='succeeded'&&scopeEqual(a.scope,decision?.scope)&&arr(d.timeline).some(t=>t.id===a.decision_id&&t.payload?.action_revision===c.action_revision)); const allowed=outcome==='ACT'&&!c.policy_pending&&!alreadyExecuted;const pendingReviews=arr(d.reviews).filter(r=>['open','pending','deferred'].includes(r.status));
 const outcomeTitles={ACT:'Ready for the next step',CLARIFY:'More information needed',WAIT:'Waiting for a reply',HUMAN_REVIEW:'Your decision needed',STOP_ACTION:'Action paused',NO_FURTHER_ACTION:'No further action needed',UNASSESSED:'Ready to review'};
 return `<div class="case-header"><div><div class="eyebrow">Request ${esc(shortID(c.id))}</div><h2>${esc(c.title)}</h2><div class="case-reference"><span>${esc(c.property_ref||'Property not established')}</span><span class="separator">/</span><span>${esc(human(c.category||'Maintenance'))}</span><span class="separator">/</span><span>Revision ${esc(c.revision??1)}</span></div></div><div class="actions"><button class="btn" data-action="proposal">Edit next action</button><button class="btn primary" data-action="add-evidence">${icon('plus')}Add evidence</button></div></div>${c.policy_pending?'<div class="notice warning"><strong>Policy changed.</strong> Reassess this case against the published policy before an action can be released.</div>':''}<div class="decision-card"><div class="decision-top ${outcome==='ACT'?'':outcome==='STOP_ACTION'?'stopped':'held'}"><div class="decision-icon">${icon(outcome==='ACT'?'check':outcome==='STOP_ACTION'?'alert':'hold')}</div><div class="decision-copy"><div class="eyebrow">${esc(actionLabels[p.action]||human(p.action)||'Proposed action')} · ${esc(p.work_item||'Work item not specified')}</div><h3>${esc(managerGroup(c)==='resolved'?'This repair is confirmed complete':alreadyExecuted?'Action recorded · repair not yet confirmed':outcomeTitles[outcome]||human(outcome))}</h3><p>${esc(managerGroup(c)==='resolved'?'Completion evidence is recorded for this work item.':alreadyExecuted?'The simulated action has been recorded. We still need evidence before a visit or repair can be marked complete.':decision?.next_step||c.next_step||'Evaluate the evidence and all applicable requirements for this action.')}</p></div>${statusBadge(managerGroup(c)==='resolved'?'verified_resolution':outcome)}</div><div class="decision-meta"><span>Owner <strong>${esc(roles[decision?.owner||c.owner]||human(decision?.owner||c.owner||'case_manager'))}</strong></span><span>Policy <strong>${esc(decision?.policy_version||'Not yet assessed')}</strong></span><span><strong>${blockers.length}</strong> ${blockers.length===1?'check to resolve':'checks to resolve'}</span><div class="actions">${pendingReviews.length?`<button class="btn primary small" data-action="open-case-reviews">${icon('people')}Review ${pendingReviews.length} ${pendingReviews.length===1?'decision':'decisions'}</button>`:''}<button class="btn small" data-action="evaluate">${icon('refresh')}Reassess</button><button class="btn primary small" data-action="execute" ${allowed?'':'disabled'}>${alreadyExecuted?'Action recorded':'Simulate action'} ${icon('arrow')}</button></div></div></div><div class="two-col"><section class="panel"><div class="panel-head"><h3>What is needed to proceed</h3><span class="small muted">All checks must pass</span></div>${checks.length?`<div class="check-list">${[...checks,...blockers.filter(b=>!checks.some(c=>c.key===b.key))].map(check=>renderCheck(check,blockers)).join('')}</div>`:empty('No assessment yet','Run a policy assessment to see the requirements and evidence for this action.')}</section><section class="panel"><div class="panel-head"><h3>About this request</h3><span class="tag">Revision ${esc(c.action_revision??1)}</span></div><div class="panel-body"><dl class="key-value"><dt>Action</dt><dd>${esc(actionLabels[p.action]||human(p.action))}</dd><dt>Work item</dt><dd>${esc(p.work_item||'Not established')}</dd><dt>Provider</dt><dd>${esc(p.provider||'Not established')}</dd><dt>Access method</dt><dd>${esc(human(p.access_method||'Not established'))}</dd><dt>Profile</dt><dd>Demonstration</dd><dt>Case status</dt><dd>${esc(human(c.status||'open'))}</dd><dt>Completion</dt><dd>${esc(human(c.completion_state||'Not verified'))}</dd><dt>Last verified action</dt><dd>${esc(lastActionText(c.last_verified_action))}</dd></dl><div class="report-label">Original report</div><blockquote class="report-quote">${esc(d.evidence?.[0]?.text||'No intake text available.')}</blockquote>${renderInterpretation(c.interpretation)}<div class="claim-scope">${esc(scopeText(p.scope))}</div><p class="layout-1 small muted">A source assertion remains unverified until a permitted role records a sourced decision.</p></div></section></div><section class="panel"><div class="tab-bar" role="tablist" aria-label="Case record"><button class="record-tab ${state.recordTab==='evidence'?'active':''}" data-tab="evidence" role="tab" aria-selected="${state.recordTab==='evidence'}">Evidence <span class="muted">${arr(d.evidence).length}</span></button><button class="record-tab ${state.recordTab==='reviews'?'active':''}" data-tab="reviews" role="tab" aria-selected="${state.recordTab==='reviews'}">Human review <span class="muted">${pendingReviews.length}</span></button><button class="record-tab ${state.recordTab==='timeline'?'active':''}" data-tab="timeline" role="tab" aria-selected="${state.recordTab==='timeline'}">Timeline <span class="muted">${arr(d.timeline).length}</span></button><button class="record-tab ${state.recordTab==='actions'?'active':''}" data-tab="actions" role="tab" aria-selected="${state.recordTab==='actions'}">Action history</button></div><div id="case-record-panel" class="panel-body" role="tabpanel" tabindex="-1" aria-label="${state.recordTab==='reviews'?'Human review':human(state.recordTab)}">${state.recordTab==='reviews'?renderCaseReviews(d):state.recordTab==='timeline'?renderTimeline(d):state.recordTab==='actions'?renderActionHistory(d):renderEvidence(d)}</div></section>`;
}
function lastActionText(value){if(!value)return 'None recorded';if(typeof value==='string')return value;return `${actionLabels[value.action||value.scope?.action]||human(value.action||value.scope?.action||value.status||'Recorded action')}${value.created_at||value.verified_at?' · '+fmtDate(value.verified_at||value.created_at):''}`;}
function renderInterpretation(value){if(!value)return '';const mode=value.mode||'unavailable';return `<div class="interpretation-summary"><div class="item-head"><strong>Derived intake interpretation</strong><span class="tag">${esc(mode)}</span></div>${value.summary?`<p>${esc(value.summary)}</p>`:''}${value.source_quote?`<p><strong>Source quotation:</strong> “${esc(value.source_quote)}”</p>`:'<p>No supporting source quotation is recorded.</p>'}<p class="muted">This interpretation does not verify permissions or work authority.</p>${arr(value.uncertainties).length?`<p class="muted">${esc(value.uncertainties.join(' '))}</p>`:''}</div>`;}

function renderCheck(check,blockers){const b=blockers.find(x=>x.key===check.key);return `<div class="check"><div class="check-main"><div class="check-name">${esc(check.key==='finance'?'Financial review':factLabels[check.key]||human(check.key))}</div><div class="check-reason">${esc(check.reason||'No reason recorded.')}${b?.owner?` <span>Owner: ${esc(roles[b.owner]||human(b.owner))}.</span>`:''}</div>${renderLinks(check)}</div>${statusBadge(check.status)}</div>`;}
function renderLinks(item){const sources=arr(item.source_ids),claims=arr(item.claim_ids);return sources.length||claims.length?`<div class="check-links">${sources.map(id=>`<button class="inline-link" data-source-id="${esc(id)}">Source ${esc(shortID(id))}</button>`).join('')}${claims.map(id=>`<button class="inline-link" data-claim-id="${esc(id)}">Claim ${esc(shortID(id))}</button>`).join('')}</div>`:'';}
function renderEvidence(d){const superseded=new Set(arr(d.claims).filter(c=>c.verified).flatMap(c=>arr(c.supersedes)));return arr(d.evidence).length?`<div class="notice">Original sources are preserved. Claims are labelled separately; adding a source does not create access consent or work authority.</div>${d.evidence.map(e=>`<article class="evidence-item" id="source-${esc(e.id)}"><div class="item-head"><div><h4>${esc(e.source_label||'Source evidence')}</h4><span class="small muted">${esc(shortID(e.id))} · ${fmtDate(e.created_at)}</span></div><span class="tag">Preserved source</span></div><div class="source-text">${esc(e.text||'No readable text recorded.')}</div>${arr(d.claims).filter(c=>c.source_id===e.id).map(c=>renderClaim({...c,superseded_by:superseded.has(c.id)})).join('')}</article>`).join('')}`:empty('No evidence recorded','Add the original message or document text, then link any claims to an exact quotation.',`<button class="btn" data-action="add-evidence">Add evidence</button>`);}
function renderClaim(c){return `<div class="claim-row ${c.superseded_by?'superseded':''}" id="claim-${esc(c.id)}"><div><strong>${esc(factLabels[c.key]||human(c.key))}</strong><div class="claim-scope">Claim ${esc(shortID(c.id))}</div></div><div><div class="claim-value">${esc(c.key==='total'?`£${Number(c.value).toFixed(2)}`:typeof c.value==='boolean'?(factValues[c.key]?.[c.value?0:1]||String(c.value)):String(c.value))}</div><div class="claim-quote">“${esc(c.source_quote||'No source quotation')}”</div><div class="claim-scope">${esc(scopeText(c.scope))}</div>${arr(c.supersedes).length?`<div class="claim-scope">Explicitly supersedes ${esc(c.supersedes.map(shortID).join(', '))}</div>`:''}</div><span class="tag">${c.superseded_by?'Superseded':c.verified?'Verified record':'Source assertion'}</span></div>`;}
function renderCaseReviews(d){const reviews=arr(d.reviews);return `${reviews.length?reviews.map(r=>renderReview(r,d.case,false,d)).join(''):empty('No human reviews','Any required decision will appear here with its exact scope and the remaining blockers.')}${arr(d.questions).length?`<div class="form-section"><h3>Tracked clarification requests</h3>${d.questions.map(q=>`<div class="review-card"><div class="item-head"><h4>${esc(q.question||q.text||factLabels[q.key]||'Clarification')}</h4>${statusBadge(q.status||'pending')}</div><p class="small muted">${esc(q.next_step||q.reason||'A relevant answer is required. Silence does not satisfy the requirement.')}</p><div class="small muted">Deadline: ${fmtDate(q.deadline||q.escalate_at)} · Reminders: ${esc(q.reminder_count??q.reminders??0)}</div></div>`).join('')}</div>`:''}<div class="layout-2 actions"><button class="btn small" data-action="tick">${icon('clock')}Reassess timers</button><span class="small muted">Uses the current time. A timer cannot grant consent.</span></div>`;}
function currentOtherBlockers(review,detail){return arr(detail?.decision?.blockers).filter(b=>b.key!==review.key);}
function renderReview(r,c,inbox=false,detail=null){
 const other=currentOtherBlockers(r,detail||r._detail||state.caseDetails?.[c.id]||state.detail),actionable=['open','pending','deferred'].includes(r.status),canCorrect=Object.hasOwn(factLabels,r.key),canApprove=['authority','finance'].includes(r.key)||(String(r.key).startsWith('rule:')&&String(r.question).includes('human review'));
 const button=(label,response,cls='')=>`<button class="btn small ${cls}" data-review-id="${esc(r.id)}" data-review-response="${response}" data-review-case="${esc(c.id)}">${label}</button>`;
 return `<article class="review-card" id="review-${esc(r.id)}"><div class="item-head"><div class="eyebrow">${esc(r.key==='finance'?'Financial review':factLabels[r.key]||human(r.key||'Scoped decision'))} · ${esc(roles[r.owner]||human(r.owner||'reviewer'))}</div>${statusBadge(r.status)}</div>${inbox?`<p class="review-context"><button class="inline-link" data-case-id="${esc(c.id)}">${esc(c.title)}</button> · ${esc(c.property_ref)}</p>`:''}<div class="review-question">${esc(r.question||'Review the specified requirement against source evidence.')}</div><div class="review-detail"><p><strong>Proposed action:</strong> ${esc(actionLabels[c.proposal?.action]||human(c.proposal?.action))} · ${esc(c.proposal?.work_item||'Not specified')}</p><p><strong>Scope:</strong> ${esc(scopeText(r.scope)||'See the case proposal.')}</p><p><strong>Policy:</strong> ${esc(r.policy_version||'Not recorded')} · <strong>Action revision:</strong> ${esc(r.action_revision||'Not recorded')}</p><p><strong>Other checks still needed:</strong> ${other.length?esc(other.map(b=>typeof b==='string'?(factLabels[b]||human(b)):(factLabels[b.key]||b.reason||human(b.key))).join('; ')):'None in the current assessment.'}</p><p><strong>Next:</strong> Recording this decision rechecks the request. Any other checks still need to pass.</p>${r.expires_at?`<p><strong>Review expires:</strong> ${fmtDate(r.expires_at)}</p>`:''}${r.response?.deadline?`<p><strong>Deferred until:</strong> ${fmtDate(r.response.deadline)}</p>`:''}${renderLinks(r)}</div>${actionable?`<div class="actions">${canCorrect?button('Verify a detail','correct','primary'):''}${canApprove?button('Approve this scope','approve'):''}${button('Request more evidence','more_evidence')}${button('Review later','defer')}${button('Reject this action','reject','danger')}</div>`:`<p class="small muted">This review is ${esc(human(r.status).toLowerCase())}. Any subsequent decision requires a current review.</p>${r.response&&r.status!=='superseded'?`<button class="btn small" data-action="policy-from-review" data-policy-review="${esc(r.id)}">${icon('spark')}Review suggested policy</button>`:''}`}</article>`;
}
function timelineSummary(t){const p=t.payload||{};return p.message||p.reason||p.next_step||p.question||(p.outcome?`Assessment outcome: ${human(p.outcome)}`:p.title||'');}
function renderTimeline(d){return arr(d.timeline).length?`<ol class="timeline">${[...d.timeline].reverse().map(t=>`<li><div class="timeline-time">${fmtDate(t.created_at)}</div><strong>${esc(human(t.kind||t.type||'Case updated'))}</strong>${timelineSummary(t)?`<p>${esc(timelineSummary(t))}</p>`:''}${t.payload?.policy_version?`<p>Policy ${esc(t.payload.policy_version)}</p>`:''}</li>`).join('')}</ol>`:empty('The case timeline starts here','New evidence, decisions, reassessments and simulated actions will be recorded.');}
function renderActionHistory(d){return `<div class="notice">The native coordinator automatically executes authorised simulated actions after a fresh check. Manual controls can test successful or uncertain adapter results. No real communications or bookings occur. An action record does not prove that a visit or repair happened.</div>${arr(d.actions).some(a=>a.status==='uncertain')?'<div class="notice warning">A result is uncertain. Read the simulated provider receipt before another attempt. <button class="btn small" data-action="reconcile">Reconcile simulated result</button></div>':''}${arr(d.actions).length?d.actions.map(a=>`<div class="action-record"><div><strong>${esc(actionLabels[a.scope?.action]||human(a.scope?.action)||'Simulated action')}</strong><p>${esc(shortID(a.id))} · ${fmtDate(a.created_at)}</p><p>${esc(a.reason||a.message||'Simulated adapter result recorded.')}</p></div><div>${statusBadge(a.status||'unknown')}</div></div>`).join(''):empty('No actions executed','Actions can run only after the latest assessment passes every applicable requirement.')}`;}

function renderInbox(){$('#app').innerHTML=`<div class="page"><div class="page-heading"><div><div class="eyebrow">Human review</div><h1>Decisions that need a person.</h1><p>See what needs your judgement, record a decision, and keep the request moving.</p></div><button class="btn" data-action="refresh-inbox">${icon('refresh')}Refresh inbox</button></div><div class="notice">Current demo role: <strong>${esc(roles[state.session?.actor?.role]||'Case manager')}</strong>. Each decision applies to the work shown. Other permissions and checks still need to be satisfied.</div><div class="review-list">${state.inbox.length?state.inbox.map(r=>renderReview(r,r._case,true)).join(''):empty('No open reviews','Requests appear here when a decision needs a person.',`<button class="btn" data-view="cases">Go to requests</button>`)}</div></div>`;}

function showNewCase(){modal('Open a maintenance case','Record the report as supplied. Unknowns remain unknown until evidence supports them.',`<form id="new-case-form"><div class="form-error" role="alert"></div><div class="form-grid">${field('Case title','title','', 'text',true)}${selectField('Proposed action','action',actionLabels,'request_quote',true)}<div class="form-field"><label for="property_ref">Property reference</label><input id="property_ref" name="property_ref" list="demo-properties" required><datalist id="demo-properties"><option value="DEMO-FLAT-1">Trusted demonstration directory</option></datalist><small>DEMO-FLAT-1 has a preconfigured demo identity and contact route. Other references begin unverified.</small></div>${selectField('Work category','category',categoryLabels,'other')}${textField('Original report','report','','Preserve the sender’s wording. Do not include real personal details in this demonstration.',true)}${field('Work item','work_item','', 'text',true)}${field('Proposed provider','provider','Demo contractor')}${selectField('Proposed access method','access_method',{tenant_present:'Tenant present',management_keys:'Management keys',contractor_keys:'Contractor keys',no_entry:'No entry required'},'tenant_present')}</div><div class="layout-2 notice">The selected action is assessed independently. It remains held until every applicable requirement is satisfied.</div>${formFooter('Create case')}</form>`);$$('#new-case-form input').filter(i=>['title','property_ref','work_item'].includes(i.name)).forEach(i=>i.required=true);}
async function showBuildImport(){
 modal('Import a BUILD case','Choose a chronological history prefix from the allowed development partition.','<div class="loading-state">Loading allowed cases…</div>',true);
 const data=await api('/api/build-cases');state.buildCases=arr(data?.cases||data);
 $('#modal-content .modal-body').innerHTML=`<div class="notice">Only events up to the selected point enter intake. Later history, eventual outcomes and attachments remain withheld. Original reports and unverified claims stay distinct.</div><div class="build-list">${state.buildCases.map(c=>{const id=c.case_id||c.id;return `<article class="build-card"><div class="eyebrow">BUILD ${esc(id)}</div><h3>Case ${esc(id)}</h3><p>${esc(c.preview||'First event available for import.')}</p><div class="form-field"><label for="events-${esc(id)}">Events to include</label><input type="number" id="events-${esc(id)}" value="1" min="1" max="${Number(c.history_events)||1}" step="1" required><small>Starts with event 1; maximum ${Number(c.history_events)||1}. Changing the number does not reveal later events until requested.</small></div><div class="actions gap-top"><button class="btn small" data-snapshot-id="${esc(id)}">Inspect selected prefix</button><button class="btn small" data-import-id="${esc(id)}">Import selected prefix</button></div><details class="build-snapshot hidden"><summary>Selected source prefix</summary><pre class="source-text"></pre></details></article>`;}).join('')}</div>`;
}
function showProposal(){const p=state.detail.case.proposal||{};modal('Edit the proposed action','Changing the proposal creates a new action revision and requires a fresh assessment.',`<form id="proposal-form"><div class="form-error" role="alert"></div><div class="form-grid">${selectField('Proposed action','action',actionLabels,p.action,true)}${selectField('Work category','category',categoryLabels,state.detail.case.category,true)}${field('Work item','work_item',p.work_item,'text',true)}${field('Provider','provider',p.provider)}${selectField('Access method','access_method',{tenant_present:'Tenant present',management_keys:'Management keys',contractor_keys:'Contractor keys',no_entry:'No entry required'},p.access_method)}</div><div class="layout-2 notice">Existing approvals apply only to their recorded scope. A changed work item, provider or access method may need new evidence.</div>${formFooter('Save proposal')}</form>`);}
let claimCounter=0;
function claimForm(){const n=claimCounter++;return `<div class="form-claim" data-claim-number="${n}"><div class="rule-top"><strong>Source-linked claim</strong><button type="button" class="btn small" data-action="remove-claim">Remove</button></div><div class="form-grid"><div class="form-field"><label for="claim-key-${n}">Specific fact</label><select id="claim-key-${n}" class="claim-key">${options(factLabels,'access')}</select></div><div class="form-field"><label for="claim-value-${n}">What the source states</label><div class="claim-value-control"><select id="claim-value-${n}" class="claim-input">${options({'true':factValues.access[0],'false':factValues.access[1]},'true')}</select></div></div><div class="form-field full"><label for="claim-quote-${n}">Exact source quotation</label><textarea id="claim-quote-${n}" class="claim-quote-input" required placeholder="Copy the words from the source text above."></textarea><small>The quotation must occur exactly in the preserved text. It is evidence of an assertion, not independent verification.</small></div></div></div>`;}
function showEvidence(){claimCounter=0;modal('Add source evidence','Keep the original text and its claims distinct. A permitted role must verify any material claim.',`<form id="evidence-form"><div class="form-error" role="alert"></div><div class="form-grid">${field('Source label','source_label','','text',true,'For example: tenant message, contractor report, or recorded call note.')}${textField('Original source text','text','','Paste the supplied wording. Do not describe an attachment you have not inspected.',true)}</div><div class="form-section"><div class="item-head"><div><h3>Claims from this source</h3><p class="small muted">Optional. Each claim needs an exact quotation and applies to the current proposal scope.</p></div><button type="button" class="btn small" data-action="add-claim">${icon('plus')}Add claim</button></div><div id="evidence-claims"></div><p class="small muted"><strong>Current scope:</strong> ${esc(scopeText(currentScope()))}</p><p class="small muted">To correct an existing claim, add the new source here, then use the scoped human review to record an evidenced correction.</p></div>${formFooter('Save evidence')}</form>`,true);$('#source_label').required=true;}
async function showReview(id,response,caseID){
 const [detail,policies]=await Promise.all([api(`/api/cases/${encodeURIComponent(caseID)}`),api('/api/policies')]);
 const review=arr(detail.reviews).find(r=>r.id===id);if(!review||!['open','deferred','pending'].includes(review.status))throw new Error('This review is no longer current. Refresh and use the active review.');
 const superseded=new Set(arr(detail.claims).filter(c=>c.verified).flatMap(c=>arr(c.supersedes))),matching=arr(detail.claims).filter(c=>c.key===review.key&&!superseded.has(c.id)&&scopeMatches(c.scope,review.scope));
 const title={correct:'Verify a detail',approve:'Approve this scope',reject:'Reject this action',defer:'Review later',more_evidence:'Request more evidence'}[response],canRespond=currentRole()===review.owner;
 const hours=Number(policies.active.settings.approval_hours),expiry=localDateInput(new Date(Date.now()+Math.min(hours*.9,24)*3600000)),deadline=localDateInput(new Date(Date.now()+24*3600000));
 modal(title,review.question||'Respond to the scoped review.',`<form id="review-form" data-review-id="${esc(id)}" data-review-case="${esc(caseID)}" data-response="${esc(response)}"><div class="form-error" role="alert"></div><div class="notice">Required role: <strong>${esc(roles[review.owner])}</strong>. Current role: <strong>${esc(roles[currentRole()]||'Unknown')}</strong>. ${!canRespond&&state.session?.mode==='demo'?`<button type="button" class="btn small" data-action="switch-review-role" data-role="${esc(review.owner)}">Use this demonstration role</button>`:''}</div><div class="review-detail"><p><strong>Scope:</strong> ${esc(scopeText(review.scope))}</p><p><strong>Other checks still needed:</strong> ${esc(currentOtherBlockers(review,detail).map(b=>factLabels[b.key]||b.reason||human(b.key)).join(', ')||'None in the current assessment.')}</p></div><div class="form-grid">${response==='correct'?`<div class="form-field full"><label for="claim_id">Source-supported claim to verify</label><select id="claim_id" name="claim_id" required><option value="">Select a current source claim</option>${matching.map(c=>`<option value="${esc(c.id)}">${esc(c.key==='total'?`£${Number(c.value).toFixed(2)}`:factValues[c.key]?.[c.value?0:1])} — ${esc(c.source_quote)}</option>`).join('')}</select><small>${matching.length?'The selected value and source are preserved. Your reasoned correction supersedes earlier current claims for this same requirement.':'There is no supporting statement to verify for this requirement. Add the original source under Add evidence, include its claim, then return to this review.'}</small><div id="selected-review-source" class="source-text hidden"></div></div>`:response==='approve'?`<div class="form-field full"><label for="source_id">Supporting source</label><select name="source_id" id="source_id" required><option value="">Select evidence supporting this exact scope</option>${arr(detail.evidence).map(e=>`<option value="${esc(e.id)}">${esc(e.source_label)} — ${esc(shortID(e.id))}</option>`).join('')}</select><div id="selected-review-source" class="source-text hidden"></div></div>`:''}${textField('Reason for this decision','reason','',response==='defer'?'Explain why this decision is deferred. No permission is granted.':response==='more_evidence'?'Describe the specific missing evidence. This request is simulated.':'Explain how the source supports this specific decision. Other requirements remain independent.',true)}${response==='approve'||response==='correct'&&['access','keys','authority'].includes(review.key)?field('Permission expiry (local time)','expires_at',expiry,'datetime-local',true,`Must be in the future and within ${hours} hours.`):''}${response==='defer'?field('Decision deadline (local time)','deadline',deadline,'datetime-local',true,'Must be in the future and within seven days.') :''}</div><div class="form-footer"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit" ${canRespond&&!(response==='correct'&&!matching.length)?'':'disabled'}>${esc(title)}</button></div></form>`,true);
 const form=$('#review-form');form._review=review;form._detail=detail;$('#reason').minLength=5;
 if($('#expires_at'))$('#expires_at').required=true;if($('#deadline'))$('#deadline').required=true;
}
const responseLabels = {CLARIFY:'Clarify first',WAIT:'Wait for a reply','HUMAN REVIEW':'Human review immediately','STOP ACTION':'Stop the action'};
const conditionLabels = {UNKNOWN:'Is missing',CONFLICT:'Conflicts',FAIL:'Is not satisfied',PASS:'Is satisfied'};
let ruleCounter=0;
function renderStructuredPolicies(){const published=state.policies?.active,active=state.policyWorking||state.draft||published;if(!active){$('#app').innerHTML=`<div class="page">${empty('No policy is available','The policy service has not returned an active version.')}</div>`;return;}const s=active.settings||{},canEdit=state.session?.actor?.role==='policy_editor';ruleCounter=0;
 $('#app').innerHTML=`<div class="page"><div class="page-heading"><div><div class="eyebrow">Policy settings</div><h1>Change the rule. See the effect.</h1><p>Draft a policy, compare its effect on saved cases, then publish a version.</p></div><span class="tag">${canEdit?'Policy editor session':'Read-only in this role'}</span></div>${!canEdit?'<div class="notice">Switch the demo role session to <strong>Policy editor</strong> to change settings. Other roles can inspect the active policy.</div>':''}<ol class="policy-stages" aria-label="Policy publication process"><li>1. Draft</li><li>2. Test saved cases</li><li>3. Compare impact</li><li>4. Publish version</li></ol><div class="policy-layout"><form id="policy-form"><fieldset class="layout-3" ${canEdit?'':'disabled'}><section class="panel policy-section"><div class="panel-head"><h3><span class="section-number">1</span>Resolution preferences</h3><span class="tag">How to obtain an answer</span></div><div class="panel-body"><div class="switch-row"><div><label for="access_immediate_review">Review missing access permission immediately</label><p>When off, request the missing permission through a verified route first. Entry stays blocked in either setting.</p></div><input class="switch" type="checkbox" id="access_immediate_review" name="access_immediate_review" aria-label="Review missing access permission immediately" ${s.access_immediate_review?'checked':''}></div><div class="form-grid">${field('Working hours before first reminder','reminder_hours',s.reminder_hours??8,'number')}${field('Working hours before escalation','escalation_hours',s.escalation_hours??16,'number')}${field('Maximum reminders per question','reminder_limit',s.reminder_limit??1,'number')}${field('Approval validity (hours)','approval_hours',s.approval_hours??48,'number')}${selectField('Deputy for overdue reviews','deputy',roles,s.deputy||'case_manager',true)}${textField('Holiday dates','holiday_dates',arr(s.holiday_dates).join('\n'),'One date per line in YYYY-MM-DD format. These dates are excluded from demonstration working hours.')}</div><p class="layout-4 small muted">These timers count only working hours: Monday–Friday, 09:00–17:00 Europe/London, excluding the holiday dates above. A reply that does not answer the question does not restart its deadline.</p></div></section><section class="panel policy-section"><div class="panel-head"><h3><span class="section-number">2</span>Action requirements</h3><span class="tag">What must be supported</span></div><div class="panel-body"><div class="form-grid">${field('Financial review limit (£ inclusive)','review_limit',s.review_limit??100,'number',false,'Amounts above this limit require scoped review. Unknown is not zero.')}${selectField('Effective property profile','profile',{demo:'Demonstration organisation defaults'},s.profile||'demo')}</div><div class="layout-5 notice">Identity, consent and authority protections are enforced by the application. A setting or approval for one requirement cannot supply another person’s consent.</div><details><summary>Additional evidence required for each action</summary><p class="layout-6 small muted">These requirements add to the protected baseline. Hold Ctrl or Command to select several facts.</p><table class="requirements-table"><thead><tr><th>Action</th><th>Additional required facts</th></tr></thead><tbody>${Object.entries(actionLabels).map(([key,label])=>`<tr><td>${esc(label)}</td><td><select class="layout-7 requirement-select" data-requirement-action="${esc(key)}" multiple size="3" aria-label="Additional evidence for ${esc(label)}">${Object.entries(factLabels).map(([value,text])=>`<option value="${esc(value)}" ${arr(s.required_per_action?.[key]).includes(value)?'selected':''}>${esc(text)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></details></div></section><section class="panel policy-section"><div class="panel-head"><h3><span class="section-number">3</span>Readable rules</h3><button type="button" class="btn small" data-action="add-rule">${icon('plus')}Add rule</button></div><div class="panel-body"><p class="small muted">Combine supported checks using ALL or ANY. Every applicable rule is evaluated; one rule cannot overrule a blocker from another.</p><div id="policy-rules">${arr(active.rules).map(rule=>renderRule(rule)).join('')}</div><div id="no-rules" class="small muted ${arr(active.rules).length?'hidden':''}">No additional rules. The protected baseline still applies.</div></div></section><section class="panel policy-section"><div class="panel-body">${textField('Reason for this policy change','reason',state.policyWorking?.reason||state.draft?.reason||'','Explain the intended change for the version history.',true)}</div></section><div class="policy-actions"><p id="policy-status">${state.draft?`Editing saved draft ${esc(shortID(state.draft.id))}.`:`Working from published version ${esc(published.version)}.`}</p><div class="actions"><button type="button" class="btn" data-action="save-policy">Save draft</button><button type="button" class="btn primary" data-action="preview-policy">Test & compare ${icon('arrow')}</button></div></div></fieldset></form><aside class="policy-sidebar"><section class="panel"><div class="panel-head"><h3>Published policy</h3>${statusBadge('active')}</div><div class="panel-body"><div class="policy-version">Version ${esc(published.version)}</div><p class="small muted">New assessments use the published version. Existing held cases must be explicitly reassessed.</p><dl class="key-value"><dt>Profile</dt><dd>${esc(human(s.profile||'demo'))}</dd><dt>Saved drafts</dt><dd>${arr(state.policies.drafts).length}</dd><dt>Execution</dt><dd>Local demonstration</dd></dl></div></section><section class="panel"><div class="panel-head"><h3>Saved drafts</h3></div><div class="panel-body">${arr(state.policies.drafts).filter(d=>d.base_version===published.version).length?`<div class="form-field"><label for="saved-policy-draft">Draft based on current version</label><select id="saved-policy-draft">${arr(state.policies.drafts).filter(d=>d.base_version===published.version).reverse().map(d=>`<option value="${esc(d.id)}">${esc(d.reason)} · ${fmtDate(d.created_at)}</option>`).join('')}</select><button class="btn small" data-action="load-policy-draft" ${canEdit?'':'disabled'}>Open saved draft</button></div>`:'<p class="small muted">No draft based on the current version.</p>'}</div></section><section class="panel"><div class="panel-head"><h3>Impact preview</h3><span class="tag">Required before publish</span></div><div id="policy-preview" class="panel-body">${empty('Preview before publishing','Compare the current and draft decisions for saved cases. No actions execute during this preview.')}</div></section><section class="panel"><div class="panel-body"><h3>Each version keeps its history</h3><p class="layout-8 small muted">Evidence snapshots and past decisions retain the policy they used. Publishing does not undo a completed action or resolve an uncertain action.</p></div></section></aside></div></div>`;
 $$('input[type=number]',$('#policy-form')).forEach(input=>{input.min=['reminder_limit','review_limit'].includes(input.name)?'0':'0.1';input.max=input.name==='reminder_limit'?'5':input.name==='review_limit'?'1000000':'720';input.step=input.name==='review_limit'?'0.01':input.name==='reminder_limit'?'1':'0.1';input.required=true;});
 $$('[data-rule]',$('#policy-form')).forEach(updateRulePreview);
}
function renderRule(rule={}){const n=ruleCounter++,conditions=arr(rule.conditions).length?rule.conditions:[{key:'access',status:'UNKNOWN'}];return `<div class="rule-builder" data-rule data-rule-id="${esc(rule.id||`custom-${Date.now()}-${n}`)}"><div class="rule-top"><strong>${esc(rule.id||'New policy rule')}</strong><button type="button" class="btn small" data-action="remove-rule">Remove rule</button></div><div class="form-grid"><div class="form-field"><label for="rule-match-${n}">Condition group</label><select id="rule-match-${n}" class="rule-match">${options({all:'ALL conditions match',any:'ANY condition matches'},rule.match||'all')}</select></div><div class="form-field"><label for="rule-response-${n}">Response</label><select id="rule-response-${n}" class="rule-response">${options(responseLabels,rule.response||'HUMAN REVIEW')}</select></div><div class="form-field"><label for="rule-owner-${n}">Responsible owner</label><select id="rule-owner-${n}" class="rule-owner">${options(roles,rule.owner||'case_manager')}</select></div><div class="form-field full"><span class="field-label">When these checks match</span><div class="rule-conditions">${conditions.map(c=>conditionRow(c)).join('')}</div><button class="btn small" type="button" data-action="add-condition">Add condition</button></div><div class="form-field full"><label for="rule-actions-${n}">Applies to actions</label><select id="rule-actions-${n}" multiple size="3" class="rule-actions">${Object.entries(actionLabels).map(([v,t])=>`<option value="${esc(v)}" ${(rule.actions||['instruct_work']).includes(v)?'selected':''}>${esc(t)}</option>`).join('')}</select><small>Hold Ctrl or Command to select several actions. Select at least one.</small></div><div class="form-field"><label for="rule-property-${n}">Property scope (optional)</label><input id="rule-property-${n}" class="rule-property" value="${esc(rule.property_ref||rule.scope?.property_ref||'')}" placeholder="All properties"></div><div class="form-field"><label for="rule-category-${n}">Work category (optional)</label><select id="rule-category-${n}" class="rule-category">${options({'':'All categories',...categories},rule.category||'')}</select></div></div><div class="rule-preview" aria-live="polite"></div></div>`;}
function conditionRow(c={key:'access',status:'UNKNOWN'}){return `<div class="condition-row"><select class="condition-key" aria-label="Condition fact">${options(factLabels,c.key)}</select><select class="condition-status" aria-label="Condition status">${options(conditionLabels,c.status)}</select><button type="button" class="btn small" data-action="remove-condition" aria-label="Remove condition">×</button></div>`;}
function readRule(el){return {id:el.dataset.ruleId,match:$('.rule-match',el).value,response:$('.rule-response',el).value,owner:$('.rule-owner',el).value,conditions:$$('.condition-row',el).map(row=>({key:$('.condition-key',row).value,status:$('.condition-status',row).value})),actions:$$('.rule-actions option:checked',el).map(o=>o.value),required:true,...($('.rule-property',el).value.trim()?{property_ref:$('.rule-property',el).value.trim()}:{}),...($('.rule-category',el).value.trim()?{category:$('.rule-category',el).value.trim()}:{})};}
function updateRulePreview(el){const r=readRule(el),conditions=r.conditions.map(c=>`${factLabels[c.key]||c.key} ${(conditionLabels[c.status]||c.status).toLowerCase()}`).join(r.match==='all'?' AND ':' OR '),actions=r.actions.map(a=>actionLabels[a]||a).join(', ');$('.rule-preview',el).textContent=`When ${conditions||'a condition is selected'} affects ${actions||'a selected action'}, ${(responseLabels[r.response]||r.response).toLowerCase()}, owned by ${(roles[r.owner]||r.owner).toLowerCase()}.${r.property_ref?` Property: ${r.property_ref}.`:''}${r.category?` Category: ${r.category}.`:''}`;}
function markPolicyDirty(){state.policyWorking=policyPayload(false);state.policyDirty=true;state.preview=null;const target=$('#policy-status');if(target)target.textContent='Unpublished changes. Save and preview before publishing.';if($('#policy-preview'))$('#policy-preview').innerHTML=empty('Preview needs refreshing','The settings have changed. Preview again to compare the current draft.');}
function policyPayload(validate=true){const form=$('#policy-form');if(validate&&!form.reportValidity())throw new Error('Complete the policy settings before saving.');const f=new FormData(form),old=state.policies.active.settings||{};const settings={...old,access_immediate_review:$('#access_immediate_review').checked,profile:f.get('profile'),deputy:f.get('deputy'),holiday_dates:String(f.get('holiday_dates')||'').split(/\s+/).filter(Boolean),required_per_action:{...old.required_per_action}};if(settings.holiday_dates.some(date=>!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date))throw new Error('Enter each holiday as a valid date in YYYY-MM-DD format.');['reminder_hours','escalation_hours','reminder_limit','approval_hours','review_limit'].forEach(k=>settings[k]=Number(f.get(k)));$$('.requirement-select',form).forEach(el=>settings.required_per_action[el.dataset.requirementAction]=[...el.selectedOptions].map(o=>o.value));const rules=$$('[data-rule]',form).map(readRule);if(validate&&rules.some(r=>!r.conditions.length||!r.actions.length))throw new Error('Each custom rule needs at least one condition and one action.');if(validate&&settings.escalation_hours<=settings.reminder_hours)throw new Error('Escalation must be later than the first reminder.');return {base_version:state.policies.active.version,settings,rules,reason:f.get('reason')||'Demonstration policy adjustment'};}
async function savePolicy(showToast=true){const data=await api('/api/policies/draft','POST',policyPayload());state.draft=data.draft||data.policy||data;state.policyWorking=null;state.preview=null;state.policyDirty=false;state.policies.drafts=arr(state.policies.drafts);state.policies.drafts.push(state.draft);$('#policy-status').textContent=`Draft ${shortID(state.draft.id)} saved. Preview its effects before publishing.`;if(showToast)toast('Policy draft saved. The published policy is unchanged.');return state.draft;}
async function previewPolicy(){if(!state.draft||state.policyDirty)await savePolicy(false);const data=await api(`/api/policies/${encodeURIComponent(state.draft.id)}/preview`,'POST',{});state.preview=data;const affected=arr(data.affected);$('#policy-preview').innerHTML=`<div class="notice success"><strong>${affected.length} ${affected.length===1?'case':'cases'} compared; ${affected.filter(c=>c.changed).length} changed.</strong> This preview does not execute actions.</div>${affected.map(c=>`<div class="preview-case"><strong>${esc(c.title||c.case_id)}</strong> <span class="tag">${c.changed?'Changed':'Unchanged'}</span><div class="preview-change">${statusBadge(typeof c.before==='object'?c.before.outcome:c.before)}<span>→</span>${statusBadge(typeof c.after==='object'?c.after.outcome:c.after)}</div>${arr(c.blockers).length?`<p>Remaining: ${esc(c.blockers.map(b=>typeof b==='string'?(factLabels[b]||b):factLabels[b.key]||b.key).join(', '))}</p>`:''}</div>`).join('')}${!affected.length?'<p class="small muted">There are no saved cases to compare.</p>':''}<div class="form-section"><p class="small muted">Publishing changes future assessments. Existing pending decisions stay held for explicit reassessment.</p><button class="btn primary wide" data-action="publish-policy">Publish this previewed draft</button></div>`;$('#policy-status').textContent='Draft previewed. Review the comparison before publishing.';}

async function submitForm(form){const data=new FormData(form),values=Object.fromEntries(data.entries());
 if(form.id==='new-case-form'){const r=await api('/api/cases','POST',values);await refreshCases();const c=r.case||r;await loadDetail(c.id);state.view='cases';state.recordTab='evidence';closeModal();render();toast('Case created and recorded.');}
 if(form.id==='proposal-form'){await api(`/api/cases/${encodeURIComponent(state.selected)}/proposal`,'POST',{...values,scope:{...state.detail.case.proposal.scope}});closeModal();await refreshSelected();toast('Proposal updated. The action scope has been rechecked.');}
 if(form.id==='evidence-form'){const text=values.text,claims=$$('.form-claim',form).map(el=>{const key=$('.claim-key',el).value,raw=$('.claim-input',el).value,quote=$('.claim-quote-input',el).value;if(!quote.trim()||!text.includes(quote))throw new Error('Every claim needs an exact quotation that appears in the original source text.');return {key,value:key==='total'?Number(raw):raw==='true',scope:currentScope(),source_quote:quote};});await api(`/api/cases/${encodeURIComponent(state.selected)}/evidence`,'POST',{text,source_label:values.source_label,claims});closeModal();await refreshSelected();toast('Evidence preserved. Claims remain source assertions until verified.');}
 if(form.id==='review-form'){const response=form.dataset.response,review=form._review;const payload={decision:response,reason:values.reason,scope:review.scope};if(response==='correct'){const claim=form._detail.claims.find(c=>c.id===values.claim_id);if(!claim)throw new Error('Select a recorded claim for this requirement.');Object.assign(payload,{claim_id:claim.id,source_id:claim.source_id,key:claim.key,value:claim.value});}else payload.source_id=values.source_id;if(values.expires_at)payload.expires_at=new Date(values.expires_at).toISOString();if(values.deadline)payload.deadline=new Date(values.deadline).toISOString();await api(`/api/reviews/${encodeURIComponent(form.dataset.reviewId)}/respond`,'POST',payload);closeModal();if(state.view==='reviews'){await loadInbox();render();}else await refreshSelected();toast('Decision recorded. The other checks have been reassessed.');if(['correct','approve','reject'].includes(response)){state.policyNudge={review_id:form.dataset.reviewId};renderPolicyNudge();}}
}

document.addEventListener('click',async event=>{
 const el=event.target.closest('button,a[data-action]');if(!el||el.disabled)return;
 try {
  if(el.dataset.portal){await switchPortal(el.dataset.portal);return;}
  if(el.dataset.view){await navigate(el.dataset.view);return;}
  if(el.dataset.caseId){state.view='cases';state.recordTab='evidence';await loadDetail(el.dataset.caseId);if(state.detail&&!filteredCases().some(c=>c.id===state.selected)){state.filter=managerGroup(state.detail.case);state.query='';}$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view==='cases'));render();return;}
  if(el.dataset.filter){state.filter=el.dataset.filter;renderCases();return;}
  if(el.dataset.tab){state.recordTab=el.dataset.tab;renderCases();return;}
  if(el.dataset.sourceId||el.dataset.claimId){if(state.view==='reviews'){const review=el.closest('.review-card');const r=state.inbox.find(x=>`review-${x.id}`===review.id);if(r){state.selected=r._case.id;state.detail=r._detail;state.view='cases';state.filter=managerGroup(r._case);state.query='';$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view==='cases'));}}state.recordTab='evidence';render();const target=document.getElementById(`${el.dataset.sourceId?'source':'claim'}-${el.dataset.sourceId||el.dataset.claimId}`);target?.scrollIntoView({behavior:'smooth',block:'center'});if(target){target.classList.add('source-highlight');setTimeout(()=>target.classList.remove('source-highlight'),2400);}return;}
  if(el.dataset.importId||el.dataset.snapshotId){const id=el.dataset.importId||el.dataset.snapshotId,input=document.getElementById(`events-${id}`);if(!input.reportValidity())return;const count=Number(input.value);el.disabled=true;if(el.dataset.snapshotId){const snap=await api(`/api/build-cases/${encodeURIComponent(id)}/snapshot?event_count=${count}`);const panel=el.closest('.build-card').querySelector('.build-snapshot');panel.classList.remove('hidden');panel.open=true;$('pre',panel).textContent=snap.text||'No source text returned.';}else{const r=await api(`/api/build-cases/${encodeURIComponent(id)}/import`,'POST',{event_count:count});await refreshCases();await loadDetail((r.case||r).id);state.view='cases';state.recordTab='evidence';closeModal();render();toast(`Imported the first ${count} ${count===1?'event':'events'}. Later history remains withheld.`);}return;}
  if(el.dataset.reviewId){await showReview(el.dataset.reviewId,el.dataset.reviewResponse,el.dataset.reviewCase);return;}
  const action=el.dataset.action;if(!action)return;
  if(await portalAction(action,el))return;
  if(action==='switch-review-role'){const form=$('#review-form'),id=form.dataset.reviewId,response=form.dataset.response,cid=form.dataset.reviewCase;await api('/api/demo-session','POST',{role:el.dataset.role});state.session=await api('/api/session');$('#session-role').value=currentRole();await showReview(id,response,cid);return;}
  if(action==='load-policy-draft'){state.draft=state.policies.drafts.find(d=>d.id===$('#saved-policy-draft').value);state.policyWorking=null;state.preview=null;state.policyDirty=false;renderPolicies();return;}
  if(action==='close-modal'){closeModal();return;}
  if(action==='new-case'){showNewCase();return;}
  if(action==='build-import'){await showBuildImport();return;}
  if(action==='proposal'){showProposal();return;}
  if(action==='open-case-reviews'){state.recordTab='reviews';renderCases();const panel=$('#case-record-panel');panel?.focus({preventScroll:true});panel?.scrollIntoView({behavior:'smooth',block:'start'});return;}
  if(action==='add-evidence'){showEvidence();return;}
  if(action==='add-claim'){$('#evidence-claims').insertAdjacentHTML('beforeend',claimForm());return;}
  if(action==='remove-claim'){el.closest('.form-claim').remove();return;}
  if(action==='evaluate'){el.disabled=true;await api(`/api/cases/${encodeURIComponent(state.selected)}/evaluate`,'POST',{});await refreshSelected();toast('Current evidence and published policy reassessed.');return;}
  if(action==='reconcile'){el.disabled=true;await api(`/api/cases/${encodeURIComponent(state.selected)}/reconcile`,'POST',{});await refreshSelected();toast('Simulated provider receipt checked. The recorded result has been reconciled.');return;}
  if(action==='tick'){el.disabled=true;await api(`/api/cases/${encodeURIComponent(state.selected)}/tick`,'POST',{});await refreshSelected();toast('Pending questions reassessed against the current time.');return;}
  if(action==='execute'){modal('Simulate the permitted action','This runs a demonstration adapter. No real message, booking or work instruction is sent.',`<div class="review-detail"><p><strong>Action:</strong> ${esc(actionLabels[state.detail.case.proposal.action])}</p><p><strong>Scope:</strong> ${esc(scopeText(currentScope()))}</p></div><p class="small muted">Choose the simulated adapter result. An uncertain acknowledgement is held for reconciliation before any retry.</p><div class="form-footer"><button class="btn" data-action="execute-uncertain">Simulate uncertain result</button><button class="btn primary" data-action="execute-success">Simulate successful result</button></div>`);return;}
  if(action==='execute-success'||action==='execute-uncertain'){el.disabled=true;await api(`/api/cases/${encodeURIComponent(state.selected)}/execute`,'POST',{outcome:action==='execute-success'?'success':'uncertain'});closeModal();await refreshSelected();toast(action==='execute-success'?'Simulated result recorded. No real external action was taken.':'Uncertain result recorded. Retry requires reconciliation.');return;}
  if(action==='refresh-cases'){await refreshSelected();toast('Cases refreshed.');return;}
  if(action==='refresh-inbox'){await loadInbox();render();return;}
  if(action==='add-rule'){$('#policy-rules').insertAdjacentHTML('beforeend',renderRule());$('#no-rules').classList.add('hidden');updateRulePreview($('#policy-rules').lastElementChild);markPolicyDirty();return;}
  if(action==='remove-rule'){el.closest('[data-rule]').remove();$('#no-rules').classList.toggle('hidden',!!$$('[data-rule]').length);markPolicyDirty();return;}
  if(action==='add-condition'){const rule=el.closest('[data-rule]');$('.rule-conditions',rule).insertAdjacentHTML('beforeend',conditionRow());updateRulePreview(rule);markPolicyDirty();return;}
  if(action==='remove-condition'){const rule=el.closest('[data-rule]');el.closest('.condition-row').remove();updateRulePreview(rule);markPolicyDirty();return;}
  if(action==='save-policy'){el.disabled=true;await savePolicy();return;}
  if(action==='preview-policy'){el.disabled=true;await previewPolicy();return;}
  if(action==='publish-policy'){if(!state.preview||!state.draft||state.policyDirty)throw new Error('Preview the current draft before publishing.');el.disabled=true;await api(`/api/policies/${encodeURIComponent(state.draft.id)}/publish`,'POST',{preview_id:state.preview.preview_id});state.policyAssistant=null;state.policySourceReview=null;state.policyText='';await refreshCases();state.policies=await api('/api/policies');state.draft=null;state.policyWorking=null;state.preview=null;state.policyDirty=false;renderPolicies();toast('Policy published. Pending cases require explicit reassessment.');return;}
 } catch(error){if(error.name!=='AbortError')toast(error.message,true);}finally{if(el.isConnected)el.disabled=false;}
});
document.addEventListener('submit',async event=>{if(event.target.id==='tenant-form'){event.preventDefault();await sendTenantMessage();return;}if(event.target.id==='policy-assistant-form'){event.preventDefault();await interpretPolicy();return;}if(!['new-case-form','proposal-form','evidence-form','review-form'].includes(event.target.id)){event.preventDefault();return;}event.preventDefault();const form=event.target,submit=$('[type=submit]',form);$('.form-error',form).textContent='';submit.disabled=true;try{await submitForm(form);}catch(error){$('.form-error',form).textContent=error.message;$('.form-error',form).scrollIntoView({block:'nearest'});}finally{if(submit.isConnected)submit.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='tenant-message'){state.tenantText=event.target.value;const send=$('#tenant-send');if(send)send.disabled=state.tenantSending||!state.tenantText.trim();}if(event.target.id==='policy-text')state.policyText=event.target.value;if(event.target.id==='case-search'){state.query=event.target.value;const selectionChanged=syncQueueSelection();$('#case-list').innerHTML=renderQueue();if(selectionChanged)$('.case-detail').innerHTML=renderRequestDetail();}if(event.target.closest('#policy-form')){markPolicyDirty();const rule=event.target.closest('[data-rule]');if(rule)updateRulePreview(rule);}});
document.addEventListener('change',async event=>{try{if(event.target.id==='session-role'){const session=await api('/api/demo-session','POST',{role:event.target.value});state.session=await api('/api/session');await refreshCases();syncQueueSelection();if(state.selected)await loadDetail(state.selected);if(state.view==='policies'){state.policies=await api('/api/policies');renderPolicies();}else if(state.view==='reviews'){await loadInbox();renderInbox();}else renderCases();toast(`Demo role changed to ${roles[event.target.value]}.`);}if(['claim_id','source_id'].includes(event.target.id)&&$('#review-form')){const form=$('#review-form'),claim=form._detail.claims.find(c=>c.id===event.target.value),source=form._detail.evidence.find(e=>e.id===(claim?.source_id||event.target.value)),box=$('#selected-review-source');if(box){box.classList.toggle('hidden',!source);box.textContent=source?`${source.source_label}\n\n${source.text}`:'';}}if(event.target.classList.contains('claim-key')){const claim=event.target.closest('.form-claim'),n=claim.dataset.claimNumber,key=event.target.value;$('.claim-value-control',claim).innerHTML=key==='total'?`<input class="claim-input" id="claim-value-${n}" type="number" min="0" step="0.01" required placeholder="Full commitment, including tax">`:`<select class="claim-input" id="claim-value-${n}">${options({'true':factValues[key][0],'false':factValues[key][1]},'true')}</select>`;}if(event.target.closest('#policy-form')){markPolicyDirty();const rule=event.target.closest('[data-rule]');if(rule)updateRulePreview(rule);}}catch(error){toast(error.message,true);}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});

async function boot(){
 $('#brand-icon').innerHTML=icon('home');
 await switchPortal('tenant');
}
document.addEventListener('click',event=>{if(event.target.closest('[data-action="reload"]'))boot();});
function mayRefresh(){return state.portal==='manager'&&!document.hidden&&!$('#modal').open&&state.view!=='policies'&&!document.activeElement?.matches('input,select,textarea')&&!document.activeElement?.closest('form');}
setInterval(async()=>{
 if(state.portal!=='manager'||!state.session?.actor||state.polling||activeRequests||!mayRefresh())return;
 state.polling=true;
 const view=state.view,selected=state.selected;
 const before=JSON.stringify({cases:state.cases,detail:state.detail,inbox:state.inbox});
 const scrollY=window.scrollY;
 try{
  await refreshCases();
  if(selected===state.selected&&state.caseDetails[selected])state.detail=state.caseDetails[selected];
  if(view==='reviews')state.inbox=Object.values(state.caseDetails).flatMap(d=>arr(d.reviews).filter(r=>['open','pending','deferred'].includes(r.status)).map(r=>({...r,_case:d.case,_detail:d})));
  if(view===state.view&&selected===state.selected&&mayRefresh()&&before!==JSON.stringify({cases:state.cases,detail:state.detail,inbox:state.inbox})){render();window.scrollTo(0,scrollY);}
 }catch(error){/* Keep the last good view; the next visible refresh can recover. */}
 finally{state.polling=false;}
},4000);


function setPortalChrome(){
 document.body.dataset.portal=state.portal;
 $$('.portal-switch button').forEach(b=>{const active=b.dataset.portal===state.portal;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 $$('.manager-only').forEach(el=>el.classList.toggle('hidden',state.portal!=='manager'));
 $('#header-context').textContent=state.portal==='tenant'?'Your home, looked after':'A little clarity for your day';
 $('#runtime-label').textContent='Local demonstration · No real communications or bookings';
 document.title=state.portal==='tenant'?'Property Desk — A little help with home':'Property Desk — Property management';
}
async function switchPortal(portal){
 if(!['tenant','manager'].includes(portal))return;
 state.portal=portal;closeModal();
 for(const [controller,path]of requestControllers){if(portal==='tenant'&&!path.startsWith('/api/tenant/'))controller.abort();if(portal==='manager'&&path.startsWith('/api/tenant/'))controller.abort();}
 setPortalChrome();
 $('#app').innerHTML='<div class="loading-state"><span class="loading-dot"></span>Getting things ready…</div>';
 try{
  if(portal==='tenant'){
   let session=await api('/api/tenant/session');
   if(!session.active)session=await api('/api/tenant/session','POST',{});
   if(state.portal!=='tenant')return;
   state.tenantSession=session;state.conversations=arr(session.conversations);
   if(state.conversation){const fresh=state.conversations.find(c=>c.id===state.conversation.id);if(fresh)state.conversation=fresh;}
   renderTenant();
  }else{
   state.session=await api('/api/session');
   if(state.session.mode==='demo'&&!state.session.actor){const session=await api('/api/demo-session','POST',{role:'case_manager'});state.session=session.actor?{...state.session,...session}:await api('/api/session');}
   if(state.portal!=='manager')return;
   if(!state.session.actor)throw new Error('An authorised staff session is needed to open property management.');
   $('#session-role').value=state.session.actor.role||'case_manager';$('#session-role').disabled=state.session.mode!=='demo';
   await refreshCases();
   if(state.selected&&state.cases.some(c=>c.id===state.selected))await loadDetail(state.selected);
   if(state.view==='policies')state.policies=await api('/api/policies');
   if(state.view==='reviews')await loadInbox();
   if(state.portal==='manager')render();
  }
 }catch(error){
  if(error.name==='AbortError'||state.portal!==portal)return;
  $('#app').innerHTML=`<div class="page">${empty(portal==='tenant'?'Your conversation could not load':'Property management could not load',error.message,`<button class="btn primary" data-action="retry-portal">Try again</button>`)}</div>`;
 }
}
function tenantStage(c){if(!c)return '';if(c.status==='resolved'||c.stage==='resolved'||c.stage==='verified_resolution')return 'Resolved';if(c.status==='closed')return 'Closed';if(arr(c.missing_fields).length)return 'A few details needed';if(c.case_id)return 'Request recorded';return 'Getting the details';}
function tenantComposer(){return `<form id="tenant-form" class="tenant-composer"><label class="sr-only" for="tenant-message">Your message</label><textarea id="tenant-message" name="message" rows="3" aria-describedby="tenant-keyboard-hint" maxlength="8000" placeholder="${state.conversation?'Write your reply…':'Tell us what’s happening…'}" ${state.tenantSending?'disabled':''} required>${esc(state.tenantText)}</textarea><div class="composer-bottom"><span id="tenant-keyboard-hint" class="composer-hint">Enter to send. Shift + Enter for a new line.</span><button id="tenant-send" class="btn primary send-button" type="submit" aria-label="${state.tenantSending?'Sending message':'Send message'}" ${state.tenantSending||!state.tenantText.trim()?'disabled':''}>${state.tenantSending?icon('clock'):icon('send')}<span>${state.tenantSending?'Sending…':'Send'}</span></button></div></form>${state.tenantError?`<p class="tenant-error" role="alert">${esc(state.tenantError)} Your message is still here. You can try sending it again.</p>`:''}`;}
function renderTenant(){
 if(state.portal!=='tenant')return;
 const c=state.conversation,hasChat=!!c||!!state.tenantPendingText;
 const tools=`<div class="tenant-tools"><span>${hasChat?'A little help, one step at a time.':'Your tenant space'}</span><div class="actions">${hasChat?`<button class="btn subtle small" data-action="tenant-new">${icon('plus')}New request</button>`:''}<button class="btn subtle small" data-action="tenant-history">${icon('history')}Your requests${state.conversations.length?` <span class="nav-count">${state.conversations.length}</span>`:''}</button></div></div>`;
 if(!hasChat){
  $('#app').innerHTML=`<div class="tenant-page">${tools}<section class="tenant-home" aria-labelledby="welcome-title"><div class="welcome-mark">${icon('home')}</div><div class="eyebrow">A little help with home</div><h1 id="welcome-title">Hey, how can I help you?</h1><p class="welcome-copy">Tell me what’s happening at home.<br>I’ll help you get it to the right people, with a clear next step.</p>${tenantComposer()}<div class="prompt-chips" aria-label="Ideas to get started"><button class="prompt-chip" data-action="tenant-prompt" data-prompt="Something in my home needs fixing. ">${icon('wrench')}Something needs fixing</button><button class="prompt-chip" data-action="tenant-prompt" data-prompt="I have a problem with the heating or hot water. ">${icon('thermometer')}Heating or hot water</button><button class="prompt-chip" data-action="tenant-prompt" data-prompt="I have a problem with a door or window. ">${icon('window')}Doors or windows</button></div><div class="tenant-reassurance">${icon('message')}No forms to work through. Just tell us in your own words.</div></section></div>`;
  return;
 }
 const messages=arr(c?.messages);
 $('#app').innerHTML=`<div class="tenant-page">${tools}<section class="tenant-conversation" aria-label="Your maintenance conversation"><div class="conversation-heading"><div class="welcome-mark">${icon('home')}</div><div><h1>${esc(c?.title||'Let’s take care of it.')}</h1><p>Property Desk · Your maintenance conversation</p></div>${c?`<span class="status ${c.case_id?'active':'pending'}">${esc(tenantStage(c))}</span>`:''}</div><div id="conversation-messages" class="conversation-messages" role="log" aria-label="Conversation messages" aria-live="polite" aria-relevant="additions text">${messages.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}">${m.role==='assistant'?`<span class="message-icon">${icon('home')}</span>`:''}<div class="message-content"><span class="message-label">${m.role==='user'?'You':'Property Desk'}</span>${esc(m.text)}</div></div>`).join('')}${state.tenantPendingText?`<div class="message user"><div class="message-content"><span class="message-label">You</span>${esc(state.tenantPendingText)}</div></div><div class="message assistant"><span class="message-icon">${icon('home')}</span><div class="message-content"><span class="message-label">Property Desk</span><span class="loading-dot"></span>One moment…</div></div>`:''}</div>${c?.case_id?`<div class="tenant-summary">${icon('check')}<div><strong>Your request is recorded</strong><p>${esc(c.next_step||'You can come back to this conversation for the next step.')} Recording a request does not confirm a booking or completed repair.</p></div></div>`:''}<div class="conversation-composer">${tenantComposer()}<p class="conversation-note">Demo conversation · Use fictional names and addresses.</p></div></section></div>`;
}
function conversationProjection(data){return data?.conversation||data?.projection||data;}
async function sendTenantMessage(){
 if(state.portal!=='tenant'||state.tenantSending)return;
 const text=state.tenantText.trim();if(!text)return;
 const id=state.conversation?.id||null;
 const key=state.tenantRetry?.text===text&&state.tenantRetry?.id===id?state.tenantRetry.key:crypto.randomUUID();
 state.tenantRetry={id,text,key};state.tenantError='';state.tenantSending=true;state.tenantPendingText=text;state.tenantText='';renderTenant();
 try{
  const result=await api(id?`/api/tenant/conversations/${encodeURIComponent(id)}/messages`:'/api/tenant/conversations','POST',{text,idempotency_key:key});
  const c=conversationProjection(result);if(!c?.id)throw new Error('The reply did not include a conversation record.');
  state.conversation=c;state.conversations=[c,...state.conversations.filter(v=>v.id!==c.id)];state.tenantRetry=null;
 }catch(error){state.tenantText=text;if(error.name!=='AbortError')state.tenantError=error.message;}
 finally{state.tenantSending=false;state.tenantPendingText='';if(state.portal==='tenant'){renderTenant();$('#tenant-message')?.focus();}}
}
async function showTenantHistory(){
 modal('Your requests','Conversations saved in this local demo session.','<div class="loading-state">Loading your requests…</div>');
 const session=await api('/api/tenant/session');state.tenantSession=session;state.conversations=arr(session.conversations);
 if(state.portal!=='tenant')return;
 $('#modal-content .modal-body').innerHTML=state.conversations.length?`<div class="tenant-history-list">${[...state.conversations].sort((a,b)=>new Date(b.updated_at||0)-new Date(a.updated_at||0)).map(c=>`<button class="tenant-history-card" data-action="tenant-open" data-conversation-id="${esc(c.id)}"><span><strong>${esc(c.title||'Maintenance request')}</strong><small>${esc(tenantStage(c))} · ${fmtDate(c.updated_at)}</small></span>${icon('chevron')}</button>`).join('')}</div>`:empty('It starts with a conversation','Your requests will appear here after you send your first message.');
}
function renderPolicyNudge(){
 $('#policy-nudge')?.remove();if(state.portal!=='manager'||!state.policyNudge||state.view==='policies')return;
 const target=$('#app .page-heading');if(!target)return;
 target.insertAdjacentHTML('afterend',`<aside class="policy-nudge" id="policy-nudge" aria-label="Policy suggestion"><div><h3 class="nudge-title">${icon('spark')}Suggest a rule for similar requests?</h3><p>Review a draft suggestion for future requests. Nothing is published automatically. This decision stays specific to its original request.</p></div><div class="actions"><button class="btn primary small" data-action="policy-from-review" data-policy-review="${esc(state.policyNudge.review_id)}">Review suggested policy</button><button class="btn small" data-action="dismiss-policy-nudge">Not now</button></div></aside>`);
}
function assistantResult(){
 const r=state.policyAssistant;if(!r)return '';
 const ready=r.status==='ready';
 return `<div class="policy-assistant-result" aria-live="polite"><h3>${ready?'Suggested change':r.status==='clarification'?'More detail needed':'Suggestion needs revision'}</h3><p>${esc(r.summary||'Describe the change you want to make.')}</p>${arr(r.questions).length?`<ul>${r.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul>`:''}${arr(r.warnings).length?`<ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}${ready&&r.draft?`<button class="btn primary small" data-action="use-policy-proposal">Review suggested settings ${icon('arrow')}</button><p class="small muted gap-top">Nothing is saved or published yet. Check the settings, then preview the effect.</p>`:`<p class="small muted">Edit the description above with these details and try again.</p>`}</div>`;
}
function renderPolicies(){
 if(state.portal!=='manager')return;
 renderStructuredPolicies();
 const page=$('#app .page'),heading=$('.page-heading',page),published=state.policies?.active;if(!page||!heading||!published)return;
 const settings=published.settings||{},canEdit=currentRole()==='policy_editor';
 $('h1',heading).textContent='Your approach, made consistent.';
 $('p',heading).textContent='Tell us how you want requests handled. Review a draft, preview its effect, then publish.';
 const stage=$('.policy-stages',page);if(stage)stage.innerHTML='<li>Describe a change</li><li>Review draft</li><li>Preview impact</li><li>Publish</li>';
 const notice=$('.notice',page);if(notice?.textContent.includes('Switch the demo role session'))notice.remove();
 const layout=$('.policy-layout',page);
 const advanced=document.createElement('details');advanced.className='policy-advanced';advanced.id='policy-advanced';advanced.open=state.policyAdvanced||!!state.policyWorking||!!state.draft;
 advanced.innerHTML=`<summary>${icon('settings')}Edit settings and review drafts</summary>`;
 if(layout){layout.before(advanced);advanced.appendChild(layout);}
 advanced.addEventListener('toggle',()=>state.policyAdvanced=advanced.open);
 advanced.insertAdjacentHTML('beforebegin',`<div class="policy-intro"><section class="policy-assistant"><h2>${icon('message')}Create a policy in your own words</h2><p>Describe what should happen and when. We’ll turn supported changes into an editable draft.</p><form id="policy-assistant-form"><label for="policy-text" class="sr-only">Describe your policy</label><textarea id="policy-text" name="text" required maxlength="8000" placeholder="For example: Ask an approver to review work costing more than £150, including VAT.">${esc(state.policyText)}</textarea><div class="policy-examples" aria-label="Policy examples"><span>Try an example</span><button type="button" class="prompt-chip" data-action="policy-example" data-policy-example="Escalate missing access permission immediately">Missing access</button><button type="button" class="prompt-chip" data-action="policy-example" data-policy-example="Remind after 4 working hours and escalate after 12 working hours">Follow-up timing</button><button type="button" class="prompt-chip" data-action="policy-example" data-policy-example="Require human review when completion is missing for closing a repair">Completion evidence</button></div><div class="assistant-footer"><p>Existing identity, permission and approval checks still apply.</p><button class="btn primary" type="submit">Prepare a suggestion ${icon('arrow')}</button></div><div id="policy-assistant-error" class="tenant-error" role="alert"></div></form><div id="policy-assistant-result">${assistantResult()}</div>${!canEdit?`<div class="policy-assistant-role"><p>Your current role can explore a suggestion. A policy editor can save and publish it.</p>${state.session?.mode==='demo'?'<button class="btn small" data-action="policy-editor-role">Use policy editor role</button>':''}</div>`:''}</section><aside class="policy-overview"><div class="eyebrow">Currently published · Version ${esc(published.version)}</div><h3>A consistent next step.<br>People stay in control.</h3><div class="policy-fact"><span>Financial review</span><strong>Above £${Number(settings.review_limit||0).toLocaleString('en-GB')}</strong></div><div class="policy-fact"><span>First reminder</span><strong>${esc(settings.reminder_hours??8)} working hours</strong></div><div class="policy-fact"><span>Escalation</span><strong>${esc(settings.escalation_hours??16)} working hours</strong></div><div class="policy-fact"><span>Missing access permission</span><strong>${settings.access_immediate_review?'Human review first':'Ask for permission first'}</strong></div><p>Published changes apply to future assessments. A policy can never grant someone’s access permission.</p></aside></div>`);
 renderPolicyNudge();
}
async function interpretPolicy(){
 const form=$('#policy-assistant-form');if(!form||!form.reportValidity())return;
 const text=$('#policy-text').value.trim();if(!text)return;
 state.policyText=text;const button=$('[type=submit]',form);button.disabled=true;button.innerHTML=`${icon('clock')}Preparing suggestion…`;$('#policy-assistant-error').textContent='';
 try{state.policyAssistant=await api('/api/policy-assistant/interpret','POST',{text,...(state.policySourceReview?{review_id:state.policySourceReview}:{})});$('#policy-assistant-result').innerHTML=assistantResult();}
 catch(error){if(error.name!=='AbortError'&&$('#policy-assistant-error'))$('#policy-assistant-error').textContent=error.message;}
 finally{if(button.isConnected){button.disabled=false;button.innerHTML=`Prepare a suggestion ${icon('arrow')}`;}}
}
async function policyFromReview(reviewID){
 const suggestion=await api(`/api/policy-assistant/reviews/${encodeURIComponent(reviewID)}/suggestion`);
 state.policySourceReview=reviewID;state.policyAssistant=suggestion;state.policyText=suggestion.suggested_text||suggestion.summary||'';state.policyNudge=null;
 await navigate('policies');$('#policy-text')?.focus();window.scrollTo({top:0,behavior:'smooth'});
}
async function portalAction(action,el){
 if(action==='portal-home'){if(state.portal==='tenant'){if(state.tenantSending)return true;state.conversation=null;state.tenantText='';state.tenantError='';renderTenant();}else await navigate('cases');return true;}
 if(action==='retry-portal'){await switchPortal(state.portal);return true;}
 if(action==='tenant-prompt'){if(state.portal!=='tenant')return true;state.tenantText=el.dataset.prompt||'';renderTenant();$('#tenant-message').focus();$('#tenant-message').setSelectionRange(state.tenantText.length,state.tenantText.length);return true;}
 if(action==='tenant-new'){if(state.tenantSending)return true;state.conversation=null;state.tenantText='';state.tenantError='';state.tenantRetry=null;renderTenant();$('#tenant-message')?.focus();return true;}
 if(action==='tenant-history'){await showTenantHistory();return true;}
 if(action==='tenant-open'){const c=conversationProjection(await api(`/api/tenant/conversations/${encodeURIComponent(el.dataset.conversationId)}`));state.conversation=c;state.tenantText='';state.tenantError='';state.tenantRetry=null;closeModal();renderTenant();return true;}
 if(action==='open-first-request'){const c=filteredCases()[0];if(c){state.filter=managerGroup(c);await loadDetail(c.id);renderCases();}return true;}
 if(action==='dismiss-policy-nudge'){state.policyNudge=null;$('#policy-nudge')?.remove();return true;}
 if(action==='policy-from-review'){el.disabled=true;await policyFromReview(el.dataset.policyReview);return true;}
 if(action==='policy-example'){state.policyText=el.dataset.policyExample||'';state.policyAssistant=null;state.policySourceReview=null;$('#policy-text').value=state.policyText;$('#policy-assistant-result').innerHTML='';$('#policy-assistant-error').textContent='';$('#policy-text').focus();return true;}
 if(action==='policy-editor-role'){await api('/api/demo-session','POST',{role:'policy_editor'});state.session=await api('/api/session');$('#session-role').value='policy_editor';renderPolicies();toast('Policy editor demo role selected.');return true;}
 if(action==='use-policy-proposal'){if(!state.policyAssistant?.draft)throw new Error('Create a complete policy suggestion first.');state.policyWorking=structuredClone(state.policyAssistant.draft);state.draft=null;state.preview=null;state.policyDirty=true;state.policyAdvanced=true;renderPolicies();$('#policy-advanced')?.scrollIntoView({behavior:'smooth',block:'start'});return true;}
 return false;
}
document.addEventListener('keydown',event=>{if(event.target.id==='tenant-message'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendTenantMessage();}});
setInterval(async()=>{
 if(state.portal!=='tenant'||!state.conversation||state.tenantSending||activeRequests||document.hidden||$('#modal').open||state.tenantText.trim())return;
 const selected=state.conversation.id;
 try{const fresh=conversationProjection(await api(`/api/tenant/conversations/${encodeURIComponent(selected)}`));if(state.portal==='tenant'&&state.conversation?.id===selected&&!state.tenantText.trim()&&JSON.stringify(fresh)!==JSON.stringify(state.conversation)){const keepFocus=document.activeElement?.id==='tenant-message';state.conversation=fresh;state.conversations=[fresh,...state.conversations.filter(c=>c.id!==fresh.id)];renderTenant();if(keepFocus)$('#tenant-message')?.focus({preventScroll:true});}}
 catch(error){/* Retain the last saved conversation until the next refresh. */}
},6000);
boot();
